1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type ScenarioResult = {
41	  results: unknown[];
42	};
43	
44	const PROCESSING_FEE = 5;
45	
46	type ItemTypeSpec = {
47	  basePremium: number;
48	  insuranceValue: number;
49	};
50	
51	const ITEM_CATALOGUE: Record<string, ItemTypeSpec> = {
52	  sword: { basePremium: 100, insuranceValue: 1000 },
53	  amulet: { basePremium: 60, insuranceValue: 600 },
54	  staff: { basePremium: 80, insuranceValue: 800 },
55	  potion: { basePremium: 40, insuranceValue: 400 },
56	  rune: { basePremium: 25, insuranceValue: 250 },
57	  moonstone: { basePremium: 25, insuranceValue: 250 },
58	};
59	
60	const catalogueEntryFor = (item: Item): ItemTypeSpec => {
61	  const spec = ITEM_CATALOGUE[item.type];
62	
63	  if (spec === undefined) {
64	    throw new Error(`unknown item type: ${item.type}`);
65	  }
66	
67	  return spec;
68	};
69	
70	const basePremiumOf = (item: Item): number =>
71	  catalogueEntryFor(item).basePremium;
72	
73	const insuranceValueOf = (item: Item): number =>
74	  catalogueEntryFor(item).insuranceValue;
75	
76	const BLOCK_SIZE = 3;
77	const BLOCK_BASE_PREMIUM = 60;
78	
79	const itemsGroupedByType = (items: Item[]): Item[][] => [
80	  ...items
81	    .reduce(
82	      (groupsByType, item) =>
83	        groupsByType.set(item.type, [
84	          ...(groupsByType.get(item.type) ?? []),
85	          item,
86	        ]),
87	      new Map<string, Item[]>(),
88	    )
89	    .values(),
90	];
91	
92	const formsABlock = (itemsAlike: Item[]): boolean =>
93	  itemsAlike.length === BLOCK_SIZE;
94	
95	const basePremiumOfItemsAlike = (itemsAlike: Item[]): number =>
96	  formsABlock(itemsAlike)
97	    ? BLOCK_BASE_PREMIUM
98	    : itemsAlike.reduce((total, item) => total + basePremiumOf(item), 0);
99	
100	const totalBasePremiumOf = (items: Item[]): number =>
101	  itemsGroupedByType(items).reduce(
102	    (total, itemsAlike) => total + basePremiumOfItemsAlike(itemsAlike),
103	    0,
104	  );
105	
106	// The MHPCO rounds whichever way costs it least: premiums up, payouts down.
107	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
108	
109	const roundedDownInMHPCOsFavour = (payout: number): number =>
110	  Math.floor(payout);
111	
112	type Rule<Subject> = {
113	  appliesTo: (subject: Subject) => boolean;
114	  rate: number;
115	};
116	
117	const totalRateOf = <Subject,>(
118	  rules: Rule<Subject>[],
119	  subject: Subject,
120	): number =>
121	  rules.reduce(
122	    (rate, rule) => (rule.appliesTo(subject) ? rate + rule.rate : rate),
123	    0,
124	  );
125	
126	const CURSE_SURCHARGE_RATE = 0.5;
127	const HIGH_ENCHANTMENT_THRESHOLD = 5;
128	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
129	
130	const ITEM_SURCHARGE_RULES: Rule<Item>[] = [
131	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
132	  {
133	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
134	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
135	  },
136	];
137	
138	const itemSurchargeOf = (item: Item): number =>
139	  basePremiumOf(item) * totalRateOf(ITEM_SURCHARGE_RULES, item);
140	
141	const totalItemSurchargeOf = (items: Item[]): number =>
142	  items.reduce((total, item) => total + itemSurchargeOf(item), 0);
143	
144	const LOYALTY_YEARS_THRESHOLD = 2;
145	const LOYALTY_DISCOUNT_RATE = -0.2;
146	
147	// Levied on every policy, follow-ups included — not only on a customer's first.
148	const INSURANCE_SURCHARGE_RATE = 0.1;
149	
150	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
151	
152	type PolicyContext = {
153	  customer: Customer;
154	  previousContracts: number;
155	};
156	
157	const POLICY_MODIFIER_RULES: Rule<PolicyContext>[] = [
158	  {
159	    appliesTo: ({ customer }) =>
160	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
161	    rate: LOYALTY_DISCOUNT_RATE,
162	  },
163	  {
164	    appliesTo: ({ previousContracts }) => previousContracts > 0,
165	    rate: FOLLOW_UP_DISCOUNT_RATE,
166	  },
167	];
168	
169	const totalPolicyModifierRateOf = (policy: PolicyContext): number =>
170	  INSURANCE_SURCHARGE_RATE + totalRateOf(POLICY_MODIFIER_RULES, policy);
171	
172	const quotePremium = (items: Item[], policy: PolicyContext): number => {
173	  const basePremium = totalBasePremiumOf(items);
174	
175	  return roundedUpInMHPCOsFavour(
176	    basePremium +
177	      totalItemSurchargeOf(items) +
178	      basePremium * totalPolicyModifierRateOf(policy) +
179	      PROCESSING_FEE,
180	  );
181	};
182	
183	const DEDUCTIBLE = 100;
184	const CAP_MULTIPLIER = 2;
185	
186	const insuranceSumOf = (items: Item[]): number =>
187	  items.reduce((total, item) => total + insuranceValueOf(item), 0);
188	
189	const payoutCapOf = (items: Item[]): number =>
190	  CAP_MULTIPLIER * insuranceSumOf(items);
191	
192	const HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
193	const HALVED_REIMBURSEMENT_RATE = 0.5;
194	const FULL_REIMBURSEMENT_RATE = 1;
195	
196	const reimbursementRateFor = (item: Item): number =>
197	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
198	    ? HALVED_REIMBURSEMENT_RATE
199	    : FULL_REIMBURSEMENT_RATE;
200	
201	const payoutForDamage = (damage: Damage, item: Item): number =>
202	  damage.amount * reimbursementRateFor(item) - DEDUCTIBLE;
203	
204	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
205	
206	type ClaimResult = {
207	  payout: number;
208	  remainingCap: number;
209	};
210	
211	// Each damage entry is settled against a distinct insured item, so a policy
212	// covering one sword cannot pay out for two damaged swords.
213	type Settlement = {
214	  total: number;
215	  unclaimedItems: Item[];
216	};
217	
218	const NOT_FOUND = -1;
219	
220	// A damage is claimable only if it is a real loss and the policy still has an
221	// unclaimed item of that type to settle it against. Answers with that item's
222	// position, so the caller can both pay for it and strike it off.
223	const claimedItemIndexFor = (
224	  damage: Damage,
225	  unclaimedItems: Item[],
226	): number => {
227	  if (damage.amount < 0) {
228	    throw new Error(`negative damage amount: ${damage.amount}`);
229	  }
230	
231	  const claimedAgainst = unclaimedItems.findIndex(
232	    (item) => item.type === damage.itemType,
233	  );
234	
235	  if (claimedAgainst === NOT_FOUND) {
236	    throw new Error(`damaged item not insured: ${damage.itemType}`);
237	  }
238	
239	  return claimedAgainst;
240	};
241	
242	const settleDamage = (
243	  { total, unclaimedItems }: Settlement,
244	  damage: Damage,
245	): Settlement => {
246	  const claimedAgainst = claimedItemIndexFor(damage, unclaimedItems);
247	
248	  return {
249	    total: total + payoutForDamage(damage, unclaimedItems[claimedAgainst]),
250	    unclaimedItems: unclaimedItems.filter(
251	      (_, index) => index !== claimedAgainst,
252	    ),
253	  };
254	};
255	
256	const totalPayoutFor = (damages: Damage[], insuredItems: Item[]): number =>
257	  damages.reduce(settleDamage, { total: 0, unclaimedItems: insuredItems })
258	    .total;
259	
260	// A claim never pays out more than the policy has left; whatever it does pay
261	// depletes the cap by exactly that much.
262	const drawnAgainstCap = (
263	  desiredPayout: number,
264	  remainingCap: number,
265	): ClaimResult => {
266	  const payout = roundedDownInMHPCOsFavour(
267	    Math.min(desiredPayout, remainingCap),
268	  );
269	
270	  return { payout, remainingCap: remainingCap - payout };
271	};
272	
273	const settleClaim = (incident: Incident, policy: IssuedPolicy): ClaimResult =>
274	  drawnAgainstCap(
275	    totalPayoutFor(incident.damages, policy.insuredItems),
276	    policy.remainingCap,
277	  );
278	
279	// A policy, once quoted, is referred to by later claim steps via its step index.
280	// Its cap depletes as claims are paid out against it.
281	type IssuedPolicy = {
282	  insuredItems: Item[];
283	  remainingCap: number;
284	};
285	
286	// Everything a step needs to know about the steps that came before it.
287	// Policies are keyed by the index of the quote step that issued them, which is
288	// how a claim step refers to them.
289	type ScenarioHistory = {
290	  issuedPolicies: Map<number, IssuedPolicy>;
291	  results: unknown[];
292	};
293	
294	const EMPTY_HISTORY: ScenarioHistory = {
295	  issuedPolicies: new Map(),
296	  results: [],
297	};
298	
299	// Every step both records a result and leaves exactly one policy changed:
300	// a quote issues one, a claim depletes the cap of the one it draws against.
301	const withStepRecorded = (
302	  history: ScenarioHistory,
303	  policyIndex: number,
304	  policy: IssuedPolicy,
305	  result: unknown,
306	): ScenarioHistory => ({
307	  issuedPolicies: new Map(history.issuedPolicies).set(policyIndex, policy),
308	  results: [...history.results, result],
309	});
310	
311	const takeQuoteStep = (
312	  step: QuoteStep,
313	  stepIndex: number,
314	  history: ScenarioHistory,
315	  customer: Customer,
316	): ScenarioHistory =>
317	  withStepRecorded(
318	    history,
319	    stepIndex,
320	    {
321	      insuredItems: step.items,
322	      remainingCap: payoutCapOf(step.items),
323	    },
324	    {
325	      premium: quotePremium(step.items, {
326	        customer,
327	        previousContracts: history.issuedPolicies.size,
328	      }),
329	    },
330	  );
331	
332	const issuedPolicyFor = (
333	  step: ClaimStep,
334	  issuedPolicies: Map<number, IssuedPolicy>,
335	): IssuedPolicy => {
336	  const policy = issuedPolicies.get(step.policy);
337	
338	  if (policy === undefined) {
339	    throw new Error(`claim against unknown policy: ${step.policy}`);
340	  }
341	
342	  return policy;
343	};
344	
345	const takeClaimStep = (
346	  step: ClaimStep,
347	  history: ScenarioHistory,
348	): ScenarioHistory => {
349	  const policy = issuedPolicyFor(step, history.issuedPolicies);
350	  const { payout, remainingCap } = settleClaim(step.incident, policy);
351	
352	  return withStepRecorded(
353	    history,
354	    step.policy,
355	    { ...policy, remainingCap },
356	    { payout, remainingCap },
357	  );
358	};
359	
360	export const runScenario = (scenario: Scenario): ScenarioResult => {
361	  const history = scenario.steps.reduce(
362	    (soFar, step, stepIndex) =>
363	      isQuote(step)
364	        ? takeQuoteStep(step, stepIndex, soFar, scenario.customer)
365	        : takeClaimStep(step, soFar),
366	    EMPTY_HISTORY,
367	  );
368	
369	  return { results: history.results };
370	};
